class MG {
  constructor(k){ this.k=k; this.map=new Map(); }
  add(x){
    if(this.map.has(x)) this.map.set(x,this.map.get(x)+1);
    else if(this.map.size < this.k-1) this.map.set(x,1);
    else{ for(const [v,c] of Array.from(this.map)) this.map.set(v,c-1); for(const [v,c] of Array.from(this.map)) if(this.map.get(v)<=0) this.map.delete(v);} }
  }
}
