function update(freq, heap, k, t) {
  freq[t] = (freq[t] || 0) + 1;
  if (heap.has(t)) adjust(heap, t);
  else if (heap.size < k) heap.push([freq[t], t]);
  else if (freq[t] > heap.min()[0]) heap.replace([freq[t], t]);
